CAN readonly IN native_together_alone_v1(frame: Atom) -> Atom {
  THIS left = frame.operand_1.operand_value
  THIS right = frame.operand_2.operand_value
  SAME left.kind {
    "ESSENCE_ID_VALUE_V1" -> SAME right.kind {
      "ESSENCE_ID_VALUE_V1" -> SAME digest256_equal.call(
        left.coupling_digest, right.coupling_digest
      ) {
        true -> NO IN o15_result_v1.call(frame, "IF_THEN", "COUPLING_CHECK")
        _ -> NO IN o15_result_v1.call(frame, "NO", "COUPLING_CHECK")
      }
      _ -> NO IN o15_result_unresolved_v1.call(frame, "RIGHT_ESSENCE_ID_TYPE")
    }
    _ -> NO IN o15_result_unresolved_v1.call(frame, "LEFT_ESSENCE_ID_TYPE")
  }

CAN readonly IN native_near_far_v1(frame: Atom) -> Atom {
  THIS left = frame.operand_1.operand_value
  THIS right = frame.operand_2.operand_value
  THIS boundary = frame.operand_3.operand_value
  SAME left.kind {
    "ESSENCE_ID_VALUE_V1" -> SAME right.kind {
      "ESSENCE_ID_VALUE_V1" -> SAME boundary.kind {
        "Q32_32_BOUNDARY_VALUE_V1" -> SAME boundary.proximity_class {
          "NEAR" -> NO IN o15_result_v1.call(frame, "IF_THEN", "DISTANCE_CHECK")
          "MID" -> NO IN o15_result_v1.call(frame, "NOT_SAME", "DISTANCE_CHECK")
          "FAR" -> NO IN o15_result_v1.call(frame, "NO", "DISTANCE_CHECK")
          "UNRESOLVED" -> NO IN o15_result_v1.call(frame, "MAYBE", "DISTANCE_CHECK")
          _ -> NO IN o15_result_unresolved_v1.call(frame, "INVALID_PROXIMITY_CLASS")
        }
        _ -> NO IN o15_result_unresolved_v1.call(frame, "Q32_BOUNDARY_TYPE")
      }
      _ -> NO IN o15_result_unresolved_v1.call(frame, "RIGHT_ESSENCE_ID_TYPE")
    }
    _ -> NO IN o15_result_unresolved_v1.call(frame, "LEFT_ESSENCE_ID_TYPE")
  }

CAN readonly IN materialize_scale_relations_v1(carrier_relations: Atom) -> Atom {
  THIS digest = sha256_digest.call(byte_seq_concat.call(
    byte_seq_leaf.call(MANY [83 67 86 49]),
    digest256_to_bytes.call(carrier_relations.repair_adjacency_evidence.digest)
  ))
  NO IN TOGETHER {
    kind: "COMMITTED_SCALE_RELATIONS_V1"
    custody: "COMMITTED"
    boundaries: MANY [
      TOGETHER {
        kind: "INTRINSIC_NEAR_FAR_BOUNDARY_V1"
        left_witness: "WHENCE"
        right_witness: "WHICH"
        relation_basis: "SHARED_BLIND_PAIR_02_09"
        proximity_class: "NEAR"
        digest: digest
      }
    ]
    operand_values: MANY []
    digest: digest
  }
}

// GROUND_REACTION_FIBER_V1
// Horizontal order preserves the multiset. Vertical proposals preserve K_id^min.
// Missing governed evidence never creates an edge.
IN ground_reaction_fiber_v1 {
  CAN readonly IN admit_horizontal_cover_v1(source: Atom, target: Atom, proposal: Atom) -> Atom {
    SAME source.verdict { "IF_THEN" -> NONE _ -> NO IN source }
    SAME target.verdict { "IF_THEN" -> NONE _ -> NO IN target }
    SAME source.arrangement.multiset { target.arrangement.multiset -> NONE _ -> NO IN TOGETHER {
      kind: "HORIZONTAL_COVER_V1" verdict: "NOT_SAME"
      first_failure_locus: "MULTISET_CHANGED"
    } }
    SAME proposal.vertical_conversion { false -> NONE _ -> NO IN TOGETHER {
      kind: "HORIZONTAL_COVER_V1" verdict: "NOT_SAME"
      first_failure_locus: "VERTICAL_PROPOSAL_AT_HORIZONTAL_BOUNDARY"
    } }
    SAME proposal.complete_directional_witness {
      true -> NONE
      _ -> NO IN TOGETHER {
        kind: "HORIZONTAL_COVER_V1" verdict: "MAYBE"
        first_failure_locus: "ANTISYMMETRIC_DIRECTIONAL_INVARIANT"
      }
    }
    NO IN TOGETHER {
      kind: "HORIZONTAL_COVER_V1" verdict: "IF_THEN"
      source: source.world_identity target: target.world_identity
      multiset: source.arrangement.multiset
      genealogy: proposal.genealogy
    }
  }

  CAN readonly IN admit_vertical_edge_v1(source: Atom, target: Atom, proposal: Atom) -> Atom {
    SAME proposal.vertical_conversion { true -> NONE _ -> NO IN TOGETHER {
      kind: "VERTICAL_EDGE_V1" verdict: "NOT_SAME"
      first_failure_locus: "HORIZONTAL_PROPOSAL_AT_VERTICAL_BOUNDARY"
    } }
    NO IN ground_identity_conservation_v1.validate_vertical_transition_v1.call(source, target, proposal)
